```javascript
function getValuesFromNestedObject(obj, keyPath) {
  const keys = keyPath.split(".");
  let currentObj = obj;

  for (let I = 0; I < keys.length - 1; i++) {
    const key = keys[i];
    if (!currentObj || !currentObj[key]) {
      // If any intermediate key is missing, return empty array
      return [];
    }
    currentObj = currentObj[key];
  }

  const lastKey = keys[keys.length - 1];
  const values = Object.values(currentObj[lastKey]);

  // Filter out null or undefined values
  return values.filter(value => value !== null && value !== undefined);
}

// Example usage:
const data = {
  a: { b: { c: "foo", d: null }, e: ["bar", "baz"] },
  f: { g: { h: "qux" } }
};

const result1 = getValuesFromNestedObject(data, "a.b.c"); // ['foo']
const result2 = getValuesFromNestedObject(data, "a.b.d"); // []
const result3 = getValuesFromNestedObject(data, "a.b.e"); // ['bar', 'baz']
const result4 = getValuesFromNestedObject(data, "f.g.h"); // ['qux']
```

The `getValuesFromNestedObject()` function takes two arguments: the nested object (`obj`) and a path to the desired nested key (`keyPath`, in dot notation). It recursively traverses the object following the given path, returning an empty array if any intermediate key is missing. Once it reaches the last key, it extracts the values from that property using `Object.values()`. The resulting array is filtered to remove null and undefined values.

